package vn.info.error404labs.bai2;

public class UnaryDemo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int r = +1;
		System.out.println(r);
		
		r--;
		System.out.println(r);
		
		r++;
		System.out.println(r);
		
		r = -r;
		System.out.println(r);
		
		boolean sucess = false;
		System.out.println(sucess);
		System.out.println(!sucess);
	}

}
